# Generic row-wise fluid simulator, preserving original red cells.
def simulate(inp):
    a=[r[:] for r in inp]; h=len(a); w=len(a[0]); active=set()
    for r in range(h):
        # roots/existing vertical 6 on this row
        for c,v in enumerate(inp[r]):
            if v==6: active.add(c)
        newactive=set()
        for c in sorted(active):
            if c<0 or c>=w: continue
            if a[r][c]==7: a[r][c]=6
        for c in sorted(active):
            if r==h-1: continue
            if inp[r+1][c]==2:
                l=c
                while l-1>=0 and inp[r+1][l-1]==2: l-=1
                rr=c
                while rr+1<w and inp[r+1][rr+1]==2: rr+=1
                for x in range(l,rr+1):
                    if a[r][x]==7:a[r][x]=6
                newactive.update([l,rr])
            else:newactive.add(c)
        active=newactive
    return a
